export default rule;
=== findings ===
export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
  return {
    rule: rule.id,
    severity: severity || rule.severity,
    file,
    line,
    what,
    why: why || rule.why,
    fix,
    doc: rule.doc,
  };
}

// Severity overrides then acceptances, in that order, so an acceptance is judged
// against the rule the project actually runs. A reasonless acceptance is itself
// a blocking finding: the reason string is what makes the decision reviewable.
export function applyConfig(findings, config) {
  const out = [];
  for (let f of findings) {
    const override = config.rules[f.rule];
    if (override === 'advisory' || override === 'blocking') f = { ...f, severity: override };
    // A path ending in "/" accepts a whole subtree; otherwise the match is exact.
    const acceptance = config.accept.find(
      (a) => a.rule === f.rule &&
        (!a.path || a.path === f.file || (a.path.endsWith('/') && f.file.startsWith(a.path)))
    );
    if (acceptance) {
      if (typeof acceptance.reason === 'string' && acceptance.reason.trim()) continue;
      out.push({
        rule: 'config',
        severity: 'blocking',
        file: '.claudinite-checks.json',
        line: null,
        what: `acceptance for ${f.rule}${acceptance.path ? ` on ${acceptance.path}` : ''}${acceptance.pack ? ` (on the "${acceptance.pack}" pack entry)` : ''} has no reason`,
        why: 'the reason string is what makes an accepted violation reviewable',
        fix: 'add a non-empty "reason" to the acceptance entry',
        doc: 'engine/checks/README.md',
      });
    }
    out.push(f);
  }
  return out;
}

export function render(f) {
  const loc = f.line ? `${f.file}:${f.line}` : f.file;
  return [
    `[${f.severity.toUpperCase()}] ${f.rule}  ${loc}`,
    `  ${f.what}`,
    ...(f.why ? [`  Why: ${f.why}`] : []),
    `  Fix: ${f.fix}`,
    ...(f.doc ? [`  More: ${f.doc}`] : []),
  ].join('\n');
}

import { finding } from '../../engine/checks/helpers/findings.mjs';

// Corpus-integrity rule: the pack catalog README must list every pack on
// disk, so the hand-maintained index can't silently drift behind a newly
// added pack (it has, twice). Only meaningful in the Claudinite repo itself;
// a consumer tracks no registry (the corpus lives under its shared mount).
// Skills have no catalog of their own (#385): a skill is its owning pack's
// content, listed nowhere but its pack.
//
// The membership token is the pack DIRECTORY, not a README inside it: a pack
// whose whole README was the checks-and-skills table the manifest now carries
// has no README at all, and the catalog still has to list it.
const CATALOGS = [
  { kind: 'pack', member: /^packs\/([^/]+)\/pack\.mjs$/, readme: 'packs/README.md', token: (n) => `(${n}/` },
];

const rule = {
  id: 'catalog-completeness',
  severity: 'blocking',
  description: 'packs/README.md lists every packs/<name>/',
  doc: 'packs/README.md',
  why: 'a hand-maintained catalog that omits a real pack misroutes readers and hides capability; the check keeps the index honest against the tree',

  run(ctx) {
    if (!ctx.tracked.includes('engine/pack_loader/pack-registry.mjs')) {
      return [];
    }
    const out = [];
    for (const { kind, member, readme, token } of CATALOGS) {
      const text = ctx.read(readme);
      if (text === null) continue;
      const names = new Set();
      for (const f of ctx.tracked) {
        const m = member.exec(f);
        if (m) names.add(m[1]);
      }
      for (const name of [...names].sort()) {
        if (!text.includes(token(name))) {
          out.push(finding(rule, {
            file: readme,
            what: `the ${kind} "${name}" exists on disk but is not listed in ${readme}`,
            fix: `add a "${name}" entry to ${readme} (or delete the ${kind} if it is dead)`,
          }));
        }
      }
    }
    return out;
  },
};

